import { d as db } from "../../../../../../../chunks/db.js";
import { fail, error } from "@sveltejs/kit";
import { s as superValidate, z as zod } from "../../../../../../../chunks/zod.js";
import { c as clienteSchema } from "../../../../../../../chunks/cliente.js";
import "../../../../../../../chunks/formData.js";
const load = async ({ params }) => {
  const cliente = await db.cliente.findUnique({
    where: { id: params.id }
  });
  if (!cliente) {
    throw error(404, "Cliente não encontrado");
  }
  const form = await superValidate(cliente, zod(clienteSchema));
  return {
    form
  };
};
const actions = {
  default: async ({ request, params }) => {
    const form = await superValidate(request, zod(clienteSchema));
    if (!form.valid) {
      return fail(400, { form });
    }
    try {
      await db.cliente.update({
        where: { id: params.id },
        data: {
          tipo: form.data.tipo,
          nome: form.data.nome,
          nif: form.data.nif,
          endereco: form.data.endereco,
          email: form.data.email,
          pais: form.data.pais,
          caixaPostal: form.data.caixaPostal,
          cidade: form.data.cidade,
          website: form.data.website,
          telefone: form.data.telefone,
          telemovel: form.data.telemovel,
          fax: form.data.fax
        }
      });
      return { form };
    } catch (error2) {
      console.error("Error updating client:", error2);
      return fail(500, { form, error: "Erro ao atualizar cliente" });
    }
  }
};
export {
  actions,
  load
};
